var sumCounts = function(nums) {
    const n = nums.length;
    const mod = 10 ** 9 + 7;
    let res = 0;

    for (let i = 0; i < n; i++) {
        const set = new Set();

        for (let j = i; j < n; j++) {
            set.add(nums[j]);

            res = (res + (set.size * set.size) % mod) % mod;
        }
    }

    return res;
